 // Every continuation is an explicit historical decision, not a blanket extension.
 // Row: from, to, title, text, outline, map kind, optional phase/map overrides.
 function D(id,name,coord,sources,learning,rows,opt={}){
  const phases=rows.map(([from,to,title,text,_p,_k,x={}])=>phase(from,to,title,text,x.sources||sources,{learning,...x.phase}));
  const e=c.entries.some(e=>e.id===id)?continueEntry(id,phases):entry(id,'africa',opt.kind||'state',coord,name,phases);
  for(const [from,to,_t,_x,p,k='polity',x={}] of rows)if(p!==null)area(id,from,to,p,{kind:k,color:opt.color,name:opt.areaName,...x.area});
  return e;
 }
